import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chatTokenBlock, CSS_SOURCE, CHAT_CSS } from '../../tools/css-build.mjs';
import { BLOG_UI, brandMark, icon } from '../../tools/blog-components.mjs';

/**
 * v74 Apple-inspired editorial V2 on the chat homepage — ONE design source.
 * The homepage loads only style.css, so its tokens, brand mark, icons and
 * theme-color are GENERATED by the build from the content-site sources:
 * editing assets/css/src/blog.css or config/blog-ui.json re-skins both.
 */

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const read = (p) => readFileSync(join(ROOT, p), 'utf8');
const css = read(CHAT_CSS);
const html = read('index.html');

test('chat tokens are the generated copy of the blog TOKENS (no drift)', () => {
  assert.ok(css.includes(chatTokenBlock(read(CSS_SOURCE))), 'style.css chat-tokens block is stale: run node tools/build-blog.mjs');
  const handwritten = css.slice(css.indexOf('/* @end chat-tokens */'));
  for (const token of ['--paper', '--surface', '--ink', '--line', '--signal', '--font', '--ease', '--color-bg', '--color-primary', '--color-text']) {
    assert.ok(!new RegExp(`${token}:`).test(handwritten), `${token} is defined only by the generated block`);
  }
});

test('chat token block fails loudly instead of emitting a missing token', () => {
  const source = read(CSS_SOURCE);
  assert.throws(() => chatTokenBlock(source.replace('--signal-ink: #0066cc;', '')), /signal-ink/);
  assert.throws(() => chatTokenBlock('.x { color: red; }'), /TOKENS/);
});

test('homepage identity comes from the content-site sources: brand mark, icons, theme-color', () => {
  assert.ok(html.includes(`<div class="motoai-brand-mark" aria-hidden="true">${brandMark()}</div>`), 'same brand mark as every content page');
  for (const name of ['scooter', 'phone', 'tag', 'map']) {
    assert.ok(html.includes(`data-icon="${name}">${icon(name, 'motoai-icon')}</span>`), `dock icon ${name} from the shared icon set`);
  }
  assert.ok(html.includes(`aria-label="Gửi câu hỏi">${icon('send', 'motoai-icon')}</button>`), 'send icon keeps its accessible name');
  const { light, dark } = BLOG_UI.site.themeColor;
  assert.ok(html.includes(`<meta name="theme-color" content="${light}" media="(prefers-color-scheme: light)">`));
  assert.ok(html.includes(`<meta name="theme-color" content="${dark}" media="(prefers-color-scheme: dark)">`));
  assert.equal(JSON.parse(read('manifest.webmanifest')).theme_color, light, 'installed app bar matches the page');
});

test('offline shell precaches the exact stylesheet URL the homepage links', () => {
  const href = /assets\/css\/style\.css\?v=\d+/.exec(html)[0];
  assert.ok(read('service-worker.js').includes(`'./${href}'`), 'service worker precache is stale: run node tools/build-blog.mjs');
});

test('iPhone: no sticky hover — every :hover lives in the fine-pointer media block', () => {
  const pointerOnly = /@media \(hover: hover\) and \(pointer: fine\)\s*\{(?:[^{}]*\{[^}]*\})*\s*\}/g;
  const rest = css.replace(/\/\*[\s\S]*?\*\//g, '').replace(pointerOnly, '');
  assert.ok(!/:hover/.test(rest), 'a :hover outside the pointer-only block stays stuck after a tap on iPhone');
});

test('header: identity row with the content-site controls; address on its own row', () => {
  assert.match(css, /\.motoai-header\s*\{[^}]*grid-template-areas:\s*"mark title actions" "sub sub sub" "status status status";/s);
  assert.match(css, /\.motoai-status:empty\s*\{\s*display:\s*none;\s*\}/, 'no blank status row');
  assert.match(html, /<div class="motoai-header-actions">\s*<button[^>]*id="blog-theme-toggle"/);
  assert.match(css, /\.motoai-theme\s*\{[^}]*min-height:\s*44px;[^}]*min-width:\s*44px;/s);
});

test('composer: one field, iOS-safe input, visible focus ring, 44px send target', () => {
  assert.match(css, /\.motoai-composer:focus-within\s*\{[^}]*box-shadow:/, 'focus ring on the whole field');
  assert.match(css, /\.motoai-input:focus, \.motoai-input:focus-visible\s*\{\s*outline:\s*none;/, 'the field ring replaces the input outline');
  assert.match(css, /\.motoai-send\s*\{[^}]*width:\s*44px;[^}]*min-height:\s*44px;/s);
  assert.match(html, /enterkeyhint="send"/);
});

test('chips: native-feeling horizontal scroll on iPhone', () => {
  assert.match(css, /\.motoai-quick\s*\{[^}]*scroll-snap-type:\s*x proximity;/s);
  assert.match(css, /\.motoai-chip\s*\{[^}]*min-height:\s*40px;[^}]*scroll-snap-align:\s*start;/s);
});

test('hidden Agent panel children never paint an empty progress track', () => {
  assert.match(css, /\.motoai-ai-explain\[hidden\], \.motoai-ai-status\[hidden\]\s*\{\s*display:\s*none;\s*\}/);
});

test('drawer: one implementation for the chat homepage and content pages', () => {
  assert.ok(!/body\.content-page \.motoai-drawer\s*\{/.test(read(CSS_SOURCE)), 'content pages reuse the shared drawer rules');
  assert.match(css, /\.motoai-drawer\s*\{[^}]*background:\s*var\(--surface\);[^}]*box-shadow:\s*var\(--shadow-2\);/s);
  assert.match(css, /\.motoai-drawer-backdrop\s*\{[^}]*background:\s*var\(--scrim\);/s);
  assert.match(css, /\.motoai-drawer,\s*\.motoai-drawer-backdrop\s*\{\s*animation:\s*none;\s*\}/, 'reduced motion: no slide-in');
});
